package draylar.identity;

import dev.architectury.event.events.common.PlayerEvent;
import dev.architectury.networking.NetworkManager;
import draylar.identity.ability.AbilityRegistry;
import draylar.identity.api.IdentityTickHandlers;
import draylar.identity.api.PlayerFavorites;
import draylar.identity.api.PlayerIdentity;
import draylar.identity.api.PlayerUnlocks;
import draylar.identity.api.platform.IdentityConfig;
import draylar.identity.network.NetworkHandler;
import draylar.identity.network.ServerNetworking;
import draylar.identity.registry.IdentityCommands;
import draylar.identity.registry.IdentityEntityTags;
import draylar.identity.registry.IdentityEventHandlers;
import io.netty.buffer.Unpooled;
import net.minecraft.advancement.Advancement;
import net.minecraft.advancement.AdvancementProgress;
import net.minecraft.entity.EntityType;
import net.minecraft.entity.LivingEntity;
import net.minecraft.entity.mob.GuardianEntity;
import net.minecraft.entity.mob.WaterCreatureEntity;
import net.minecraft.network.PacketByteBuf;
import net.minecraft.registry.Registries;
import net.minecraft.server.network.ServerPlayerEntity;
import net.minecraft.util.Identifier;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.List;

public class Identity {

    public static final Logger LOGGER = LoggerFactory.getLogger(Identity.class);

    public void initialize() {
        IdentityEntityTags.init();
        AbilityRegistry.init();
        IdentityEventHandlers.initialize();
        IdentityCommands.init();
        ServerNetworking.initialize();
        ServerNetworking.registerUseAbilityPacketHandler();
        registerJoinSyncPacket();
        IdentityTickHandlers.initialize();
    }

    public static void registerJoinSyncPacket() {
        PlayerEvent.PLAYER_JOIN.register(player -> {
            // Send config sync packet
            PacketByteBuf packet = new PacketByteBuf(Unpooled.buffer());
            packet.writeBoolean(IdentityConfig.getInstance().enableClientSwapMenu());
            packet.writeBoolean(IdentityConfig.getInstance().showPlayerNametag());
            NetworkManager.sendToPlayer(player, NetworkHandler.CONFIG_SYNC, packet);

            // Sync unlocked Identity
            PlayerUnlocks.sync(player);

            // Sync favorites
            PlayerFavorites.sync(player);
        });
    }

    public static Identifier id(String name) {
        return new Identifier("identity", name);
    }

    public static boolean hasFlyingPermissions(ServerPlayerEntity player) {
        LivingEntity identity = PlayerIdentity.getIdentity(player);

        if(identity != null && IdentityConfig.getInstance().enableFlight() && identity.getType().isIn(IdentityEntityTags.FLYING)) {
            List<String> requiredAdvancements = IdentityConfig.getInstance().advancementsRequiredForFlight();

            // requires at least 1 advancement, check if player has them
            if(!requiredAdvancements.isEmpty()) {

                boolean hasPermission = true;
                for (String requiredAdvancement : requiredAdvancements) {
                    Advancement advancement = player.server.getAdvancementLoader().get(new Identifier(requiredAdvancement));
                    AdvancementProgress progress = player.getAdvancementTracker().getProgress(advancement);

                    if(!progress.isDone()) {
                        hasPermission = false;
                    }
                }

                return hasPermission;
            }


            return true;
        }

        return false;
    }

    public static boolean isAquatic(LivingEntity entity) {
        return entity instanceof WaterCreatureEntity || entity instanceof GuardianEntity;
    }

    public static int getCooldown(EntityType<?> type) {
        String id = Registries.ENTITY_TYPE.getId(type).toString();
        return IdentityConfig.getInstance().getAbilityCooldownMap().getOrDefault(id, 20);
    }
}

package draylar.identity.api;

import net.minecraft.server.network.ServerPlayerEntity;

public class FlightHelper {

    public static void grantFlightTo(ServerPlayerEntity player) {
        player.getAbilities().allowFlying = true;
    }

    public static boolean hasFlight(ServerPlayerEntity player) {
        return player.getAbilities().allowFlying;
    }

    public static void revokeFlight(ServerPlayerEntity player) {
        if(player.interactionManager.isSurvivalLike()) {
            player.getAbilities().allowFlying = false;
        }

        player.getAbilities().flying = false;
    }
}

package draylar.identity.api;

import draylar.identity.api.platform.IdentityConfig;
import draylar.identity.api.variant.IdentityType;
import net.minecraft.entity.Entity;
import net.minecraft.entity.LivingEntity;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.registry.Registries;
import net.minecraft.server.network.ServerPlayerEntity;
import net.minecraft.stat.Stats;
import net.minecraft.text.Text;

public class IdentityGranting {

    public static void grantByAttack(PlayerEntity player, IdentityType<?> granted) {
        if(player instanceof ServerPlayerEntity serverPlayerEntity) {
            int amountKilled = serverPlayerEntity.getStatHandler().getStat(Stats.KILLED, granted.getEntityType());

            // If the player has to kill a certain number of mobs before unlocking an Identity, check their statistic for the specific type.
            if(IdentityConfig.getInstance().requiresKillsForIdentity()) {
                String id = Registries.ENTITY_TYPE.getId(granted.getEntityType()).toString();

                // Check against a specific count requirement or the default count.
                int required = IdentityConfig.getInstance().getRequiredKillsForIdentity();
                if(IdentityConfig.getInstance().getRequiredKillsByType() != null && IdentityConfig.getInstance().getRequiredKillsByType().containsKey(id)) {
                    required = IdentityConfig.getInstance().getRequiredKillsByType().get(id);
                }

                // If the amount currently killed is less than the required amount, do not allow the player to unlock.
                if(amountKilled < required) {
                    return;
                }
            }

            boolean isNew = false;
            boolean hadPreviously = PlayerUnlocks.has(serverPlayerEntity, granted);
            boolean result = PlayerUnlocks.unlock(serverPlayerEntity, granted);

            // ensure type has not already been unlocked
            if(result && !hadPreviously) {

                // send unlock message to player if they aren't in creative and the config option is on
                if(IdentityConfig.getInstance().shouldOverlayIdentityUnlocks() && !player.isCreative()) {
                    player.sendMessage(
                            Text.translatable(
                                    "identity.unlock_entity",
                                    Text.translatable(granted.getEntityType().getTranslationKey())
                            ), true
                    );
                }

                isNew = true;
            }

            // force-morph player into new type
            Entity instanced = granted.create(player.getWorld());
            if(instanced instanceof LivingEntity) {
                if(IdentityConfig.getInstance().forceChangeNew() && isNew) {
                    PlayerIdentity.updateIdentity(serverPlayerEntity, granted, (LivingEntity) instanced);
                } else if(IdentityConfig.getInstance().forceChangeAlways()) {
                    PlayerIdentity.updateIdentity(serverPlayerEntity, granted, (LivingEntity) instanced);
                }
            }
        }
    }
}

package draylar.identity.api;

import dev.architectury.networking.NetworkManager;
import draylar.identity.impl.PlayerDataProvider;
import draylar.identity.network.NetworkHandler;
import io.netty.buffer.Unpooled;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.network.PacketByteBuf;
import net.minecraft.server.network.ServerPlayerEntity;

public class PlayerAbilities {

    /**
     * Returns an integer representing the current ability cooldown of the specified {@link PlayerEntity} in ticks.
     *
     * <p>
     * A return value of {@code 0} represents no cooldown, while 20 is 1 second.
     *
     * @param player player to retrieve ability cooldown for
     * @return cooldown, in ticks, of the specified player's ability
     */
    public static int getCooldown(PlayerEntity player) {
        return ((PlayerDataProvider) player).getAbilityCooldown();
    }

    public static boolean canUseAbility(PlayerEntity player) {
        return ((PlayerDataProvider) player).getAbilityCooldown() <= 0;
    }

    public static void setCooldown(PlayerEntity player, int cooldown) {
        ((PlayerDataProvider) player).setAbilityCooldown(cooldown);
    }

    public static void sync(ServerPlayerEntity player) {
        PacketByteBuf packet = new PacketByteBuf(Unpooled.buffer());
        packet.writeInt(((PlayerDataProvider) player).getAbilityCooldown());
        NetworkManager.sendToPlayer(player, NetworkHandler.ABILITY_SYNC, packet);
    }
}

package draylar.identity.api;

import draylar.identity.api.variant.IdentityType;
import draylar.identity.impl.PlayerDataProvider;
import draylar.identity.network.impl.FavoritePackets;
import net.minecraft.entity.EntityType;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.server.network.ServerPlayerEntity;

import java.util.Set;

public class PlayerFavorites {

    public static boolean has(PlayerEntity player, IdentityType type) {
        return type.getEntityType().equals(EntityType.PLAYER) || getFavorites(player).contains(type);
    }

    public static void favorite(ServerPlayerEntity player, IdentityType type) {
        if(!getFavorites(player).contains(type)) {
            getFavorites(player).add(type);
            PlayerAbilities.sync(player);
        }

        sync(player);
    }

    public static void unfavorite(ServerPlayerEntity player, IdentityType type) {
        if(getFavorites(player).contains(type)) {
            getFavorites(player).remove(type);
            PlayerAbilities.sync(player);
        }

        sync(player);
    }

    public static Set<IdentityType<?>> getFavorites(PlayerEntity player) {
        return ((PlayerDataProvider) player).getFavorites();
    }

    public static void sync(ServerPlayerEntity player) {
        FavoritePackets.sendFavoriteSync(player);
    }
}

package draylar.identity.api;

import draylar.identity.impl.PlayerDataProvider;
import net.minecraft.entity.player.PlayerEntity;

public class PlayerHostility {

    /**
     * Returns whether the player this component is attached to will be targeted by hostile mobs, regardless of Identity.
     *
     * <p>Hostility works on a timer, and is set when the player attacks a hostile mob.
     *
     * @return  whether this component's player will be targeted by hostile mobs, regardless of Identity
     */
    public static boolean hasHostility(PlayerEntity player) {
        return ((PlayerDataProvider) player).getRemainingHostilityTime() > 0;
    }

    /**
     * Sets this components' hostility timer to the given time in ticks.
     *
     * @param hostilityTime  time, in ticks, to set hostility timer to
     */
    public static void set(PlayerEntity player, int hostilityTime) {
        ((PlayerDataProvider) player).setRemainingHostilityTime(hostilityTime);
    }
}

package draylar.identity.api;

import dev.architectury.networking.NetworkManager;
import draylar.identity.api.variant.IdentityType;
import draylar.identity.impl.PlayerDataProvider;
import draylar.identity.network.NetworkHandler;
import io.netty.buffer.Unpooled;
import net.minecraft.entity.LivingEntity;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.nbt.NbtCompound;
import net.minecraft.network.PacketByteBuf;
import net.minecraft.registry.Registries;
import net.minecraft.server.network.ServerPlayerEntity;

public class PlayerIdentity {

    /**
     * Returns the identity associated with the {@link PlayerEntity} this component is attached to.
     *
     * <p>Note that this method may return null, which represents "no identity."
     *
     * @return the current {@link LivingEntity} identity associated with this component's player owner, or null if they have no identity equipped
     */
    public static LivingEntity getIdentity(PlayerEntity player) {
        return ((PlayerDataProvider) player).getIdentity();
    }

    public static IdentityType<?> getIdentityType(PlayerEntity player) {
        return ((PlayerDataProvider) player).getIdentityType();
    }

    /**
     * Sets the identity of the specified player.
     *
     * <p>Setting a identity refreshes the player's dimensions/hitbox, and toggles flight capabilities depending on the entity.
     * To clear this component's identity, pass null.
     *
     * @param entity {@link LivingEntity} new identity for this component, or null to clear
     */
    public static boolean updateIdentity(ServerPlayerEntity player, IdentityType<?> type, LivingEntity entity) {
        return ((PlayerDataProvider) player).updateIdentity(entity);
    }

    public static void sync(ServerPlayerEntity player) {
        sync(player, player);
    }

    public static void sync(ServerPlayerEntity changed, ServerPlayerEntity packetTarget) {
        PacketByteBuf packet = new PacketByteBuf(Unpooled.buffer());
        NbtCompound entityTag = new NbtCompound();

        // serialize current identity data to tag if it exists
        LivingEntity identity = getIdentity(changed);
        if(identity != null) {
            identity.writeNbt(entityTag);
        }

        // put entity type ID under the key "id", or "minecraft:empty" if no identity is equipped (or the identity entity type is invalid)
        packet.writeUuid(changed.getUuid());
        packet.writeString(identity == null ? "minecraft:empty" : Registries.ENTITY_TYPE.getId(identity.getType()).toString());
        packet.writeNbt(entityTag);
        NetworkManager.sendToPlayer(packetTarget, NetworkHandler.IDENTITY_SYNC, packet);
    }
}

package draylar.identity.api;

import dev.architectury.event.EventResult;
import draylar.identity.api.event.UnlockIdentityCallback;
import draylar.identity.api.variant.IdentityType;
import draylar.identity.impl.PlayerDataProvider;
import draylar.identity.network.impl.UnlockPackets;
import net.minecraft.entity.EntityType;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.server.network.ServerPlayerEntity;
import net.minecraft.util.ActionResult;

public class PlayerUnlocks {

    public static boolean unlock(ServerPlayerEntity player, IdentityType granted) {
        PlayerDataProvider provider = (PlayerDataProvider) player;
        EventResult unlock = UnlockIdentityCallback.EVENT.invoker().unlock(player, granted);

        if(unlock.asMinecraft() != ActionResult.FAIL && !provider.getUnlocked().contains(granted)) {
            provider.getUnlocked().add(granted);
            sync(player);
            PlayerAbilities.sync(player); // TODO: ???
            return true;
        } else {
            return false;
        }
    }

    public static boolean has(PlayerEntity player, IdentityType type) {
        return type.getEntityType().equals(EntityType.PLAYER) || (((PlayerDataProvider) player)).getUnlocked().contains(type);
    }

    public static void revoke(ServerPlayerEntity player, IdentityType type) {
        PlayerDataProvider provider = (PlayerDataProvider) player;

        if(provider.getUnlocked().contains(type)) {
            provider.getUnlocked().remove(type);
            sync(player);
            PlayerAbilities.sync(player); // TODO: ???
        }
    }

    public static void sync(ServerPlayerEntity player) {
        UnlockPackets.sendSyncPacket(player);
    }
}

package draylar.identity.api.variant;

import draylar.identity.impl.variant.*;
import net.minecraft.entity.Entity;
import net.minecraft.entity.EntityType;
import net.minecraft.entity.LivingEntity;
import net.minecraft.nbt.NbtCompound;
import net.minecraft.registry.Registries;
import net.minecraft.text.Text;
import net.minecraft.util.Identifier;
import net.minecraft.world.World;
import org.jetbrains.annotations.Nullable;

import java.util.*;

public class IdentityType<T extends LivingEntity> {

    private static final List<EntityType<? extends LivingEntity>> LIVING_TYPE_CASH = new ArrayList<>();
    private static final Map<EntityType<? extends LivingEntity>, TypeProvider<?>> VARIANT_BY_TYPE = new LinkedHashMap<>();
    private final EntityType<T> type;
    private final int variantData;

    static {
        VARIANT_BY_TYPE.put(EntityType.SHEEP, new SheepTypeProvider());
        VARIANT_BY_TYPE.put(EntityType.AXOLOTL, new AxolotlTypeProvider());
        VARIANT_BY_TYPE.put(EntityType.PARROT, new ParrotTypeProvider());
        VARIANT_BY_TYPE.put(EntityType.FOX, new FoxTypeProvider());
        VARIANT_BY_TYPE.put(EntityType.CAT, new CatTypeProvider());
        VARIANT_BY_TYPE.put(EntityType.SLIME, new SlimeTypeProvider());
        VARIANT_BY_TYPE.put(EntityType.FROG, new FrogTypeProvider());
    }

    public IdentityType(EntityType<T> type) {
        this.type = type;
        variantData = getDefaultVariantData(type);
    }

    private int getDefaultVariantData(EntityType<T> type) {
        if(VARIANT_BY_TYPE.containsKey(type)) {
            return VARIANT_BY_TYPE.get(type).getFallbackData();
        } else {
            return -1;
        }
    }

    public IdentityType(EntityType<T> type, int variantData) {
        this.type = type;
        this.variantData = variantData;
    }

    public IdentityType(T entity) {
        this.type = (EntityType<T>) entity.getType();

        // Discover variant data based on entity NBT data.
        @Nullable TypeProvider<T> provider = (TypeProvider<T>) VARIANT_BY_TYPE.get(type);
        if(provider != null) {
            variantData = provider.getVariantData(entity);
        } else {
            variantData = getDefaultVariantData(type);
        }
    }

    @Nullable
    public static <Z extends LivingEntity> IdentityType<Z> from(Z entity) {
        if(entity == null) {
            return null;
        }

        EntityType<Z> type = (EntityType<Z>) entity.getType();
        if(VARIANT_BY_TYPE.containsKey(type)) {
            TypeProvider<Z> typeProvider = (TypeProvider<Z>) VARIANT_BY_TYPE.get(type);
            return typeProvider.create(type, entity);
        }

        return new IdentityType<>((EntityType<Z>) entity.getType());
    }

    @Nullable
    public static IdentityType<?> from(NbtCompound compound) {
        Identifier id = new Identifier(compound.getString("EntityID"));
        if(!Registries.ENTITY_TYPE.containsId(id)) {
            return null;
        }

        return new IdentityType(Registries.ENTITY_TYPE.get(id), compound.contains("Variant") ? compound.getInt("Variant") : -1);
    }

    public static List<IdentityType<?>> getAllTypes(World world) {
        if(LIVING_TYPE_CASH.isEmpty()) {
            for (EntityType<?> type : Registries.ENTITY_TYPE) {
                Entity instance = type.create(world);
                if(instance instanceof LivingEntity) {
                    LIVING_TYPE_CASH.add((EntityType<? extends LivingEntity>) type);
                }
            }
        }

        List<IdentityType<?>> types = new ArrayList<>();
        for (EntityType<?> type : LIVING_TYPE_CASH) {
            if(VARIANT_BY_TYPE.containsKey(type)) {
                TypeProvider<?> variant = VARIANT_BY_TYPE.get(type);
                for (int i = 0; i <= variant.getRange(); i++) {
                    types.add(new IdentityType(type, i));
                }
            } else {
                types.add(new IdentityType(type));
            }
        }

        return types;
    }

    @Nullable
    public static <Z extends LivingEntity> IdentityType<Z> from(EntityType<?> entityType, int variant) {
        if(VARIANT_BY_TYPE.containsKey(entityType)) {
            TypeProvider<?> provider = VARIANT_BY_TYPE.get(entityType);
            if(variant < -1 || variant > provider.getRange()) {
                return null;
            }
        }

        return new IdentityType<>((EntityType<Z>) entityType, variant);
    }

    public NbtCompound writeCompound() {
        NbtCompound compound = new NbtCompound();
        compound.putString("EntityID", Registries.ENTITY_TYPE.getId(type).toString());
        compound.putInt("Variant", variantData);
        return compound;
    }

    public EntityType<? extends LivingEntity> getEntityType() {
        return type;
    }

    public T create(World world) {
        TypeProvider<T> typeProvider = (TypeProvider<T>) VARIANT_BY_TYPE.get(type);
        if(typeProvider != null) {
            return typeProvider.create(type, world, variantData);
        }

        return type.create(world);
    }

    public int getVariantData() {
        return variantData;
    }

    @Override
    public boolean equals(Object o) {
        if(this == o) return true;
        if(o == null || getClass() != o.getClass()) return false;
        IdentityType<?> that = (IdentityType<?>) o;
        return variantData == that.variantData && type.equals(that.type);
    }

    @Override
    public int hashCode() {
        return Objects.hash(type, variantData);
    }

    public void writeEntityNbt(NbtCompound tag) {
        NbtCompound inner = writeCompound();
        tag.put("IdentityType", inner);
    }

    public static IdentityType<?> fromEntityNbt(NbtCompound tag) {
        return from(tag.getCompound("IdentityType"));
    }

    public Text createTooltipText(T entity) {
        TypeProvider<T> provider = (TypeProvider<T>) VARIANT_BY_TYPE.get(type);
        if(provider != null) {
            return provider.modifyText(entity, Text.translatable(type.getTranslationKey()));
        }

        return Text.translatable(type.getTranslationKey());
    }
}

package draylar.identity.api.variant;

import net.minecraft.entity.EntityType;
import net.minecraft.entity.LivingEntity;
import net.minecraft.text.MutableText;
import net.minecraft.text.Text;
import net.minecraft.world.World;

import java.util.Locale;

public abstract class TypeProvider<T extends LivingEntity> {

    public IdentityType<T> create(EntityType<T> type, T entity) {
        return new IdentityType<T>((EntityType<T>) entity.getType(), getVariantData(entity));
    }

    public abstract int getVariantData(T entity);

    public abstract T create(EntityType<T> type, World world, int data);

    public abstract int getFallbackData();

    public abstract int getRange();

    public abstract Text modifyText(T entity, MutableText text);

    public final String formatTypePrefix(String prefix) {
        return String.valueOf(prefix.charAt(0)).toUpperCase(Locale.ROOT) + prefix.substring(1);
    }
}

package draylar.identity.impl.variant;

import draylar.identity.api.variant.TypeProvider;
import net.minecraft.entity.EntityType;
import net.minecraft.entity.passive.SheepEntity;
import net.minecraft.text.MutableText;
import net.minecraft.text.Text;
import net.minecraft.util.DyeColor;
import net.minecraft.world.World;

public class SheepTypeProvider extends TypeProvider<SheepEntity> {

    @Override
    public int getVariantData(SheepEntity entity) {
        return entity.getColor().ordinal();
    }

    @Override
    public SheepEntity create(EntityType<SheepEntity> type, World world, int data) {
        SheepEntity sheep = new SheepEntity(type, world);
        sheep.setColor(DyeColor.byId(data));
        return sheep;
    }

    @Override
    public int getFallbackData() {
        return DyeColor.WHITE.getId();
    }

    @Override
    public int getRange() {
        return DyeColor.BLACK.getId();
    }

    @Override
    public Text modifyText(SheepEntity sheep, MutableText text) {
        return Text.literal(formatTypePrefix(DyeColor.byId(getVariantData(sheep)).getName()) + " ").append(text);
    }
}

package draylar.identity.mixin;

import draylar.identity.api.PlayerHostility;
import draylar.identity.api.PlayerIdentity;
import draylar.identity.api.platform.IdentityConfig;
import net.minecraft.entity.EntityGroup;
import net.minecraft.entity.EntityType;
import net.minecraft.entity.LivingEntity;
import net.minecraft.entity.ai.goal.ActiveTargetGoal;
import net.minecraft.entity.boss.WitherEntity;
import net.minecraft.entity.mob.CreeperEntity;
import net.minecraft.entity.mob.Monster;
import net.minecraft.entity.player.PlayerEntity;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.Shadow;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfoReturnable;

@Mixin(ActiveTargetGoal.class)
public abstract class ActiveTargetGoalMixin extends TrackTargetGoalMixin {

    @Shadow protected LivingEntity targetEntity;

    @Inject(
            method = "start",
            at = @At("HEAD"),
            cancellable = true
    )
    private void ignoreMorphedPlayers(CallbackInfo ci) {
        if (IdentityConfig.getInstance().hostilesIgnoreHostileIdentityPlayer() && this.mob instanceof Monster && this.targetEntity instanceof PlayerEntity) {
            PlayerEntity player = (PlayerEntity) this.targetEntity;
            LivingEntity identity = PlayerIdentity.getIdentity(player);

            if(identity != null) {
                boolean hasHostility = PlayerHostility.hasHostility(player);

                // only cancel if the player does not have hostility
                if (!hasHostility) {
                    // creepers should ignore cats
                    if (this.mob instanceof CreeperEntity && identity.getType().equals(EntityType.OCELOT)) {
                        this.stop();
                        ci.cancel();
                    }

                    // withers should ignore undead
                    else if (this.mob instanceof WitherEntity && identity.getGroup().equals(EntityGroup.UNDEAD)) {
                        this.stop();
                        ci.cancel();
                    }

                    // hostile mobs (besides wither) should not target players morphed as hostile mobs
                    else if (!(this.mob instanceof WitherEntity) && identity instanceof Monster) {
                        this.stop();
                        ci.cancel();
                    }
                }
            }
        }
    }

    @Override
    protected void identity_shouldContinue(CallbackInfoReturnable<Boolean> cir) {
        // check cancelling for hostiles
        if(IdentityConfig.getInstance().hostilesIgnoreHostileIdentityPlayer() && IdentityConfig.getInstance().hostilesForgetNewHostileIdentityPlayer() && this.mob instanceof Monster && this.targetEntity instanceof PlayerEntity player) {
            LivingEntity identity = PlayerIdentity.getIdentity(player);

            if (identity != null) {
                boolean hasHostility = PlayerHostility.hasHostility(player);

                // only cancel if the player does not have hostility
                if (!hasHostility) {
                    // creepers should ignore cats
                    if (this.mob instanceof CreeperEntity && identity.getType().equals(EntityType.OCELOT)) {
                        cir.setReturnValue(false);
                    }

                    // withers should ignore undead
                    else if (this.mob instanceof WitherEntity && identity.getGroup().equals(EntityGroup.UNDEAD)) {
                        cir.setReturnValue(false);
                    }

                    // hostile mobs (besides wither) should not target players morphed as hostile mobs
                    else if (!(this.mob instanceof WitherEntity) && identity instanceof Monster) {
                        cir.setReturnValue(false);
                    }
                }
            }
        }
    }
}

package draylar.identity.mixin;

import draylar.identity.Identity;
import draylar.identity.api.IdentityGranting;
import draylar.identity.api.PlayerIdentity;
import draylar.identity.api.variant.IdentityType;
import draylar.identity.impl.NearbySongAccessor;
import draylar.identity.mixin.accessor.LivingEntityAccessor;
import draylar.identity.registry.IdentityEntityTags;
import net.fabricmc.api.EnvType;
import net.fabricmc.api.Environment;
import net.minecraft.entity.*;
import net.minecraft.entity.damage.DamageSource;
import net.minecraft.entity.effect.StatusEffect;
import net.minecraft.entity.effect.StatusEffectInstance;
import net.minecraft.entity.effect.StatusEffects;
import net.minecraft.entity.mob.SpiderEntity;
import net.minecraft.entity.mob.WaterCreatureEntity;
import net.minecraft.entity.passive.BatEntity;
import net.minecraft.entity.passive.DolphinEntity;
import net.minecraft.entity.player.PlayerEntity;
